script:
let banner = $(root_element).find("#user-profile-banner");

let email = frappe.session.user_email;
let avatar = frappe.avatar(email);

frappe.call({
	method: "frappe.client.get_value",
	args: {
		doctype: "User",
		filters: { name: frappe.session.user },
		fieldname: ["full_name"],
	},
	callback: function (r) {
		if (r.message) {
			banner.find(".full-name").text("Welcome " + r.message.full_name);
		}
	},
});

banner.find(".email").text(email);
banner.find(".avatar").html(avatar);

style:
#user-profile-banner {
	margin: 0px 0px 0px;
}

#user-profile-banner .banner {
	width: 100%;
	height: 400px;
}

#user-profile-banner .banner img {
	object-fit: cover;
	width: 100%;
	height: inherit;
	object-position: center 50%;
	border-top-left-radius: var(--border-radius-lg);
	border-top-right-radius: var(--border-radius-lg);
}

.avatar-small {
	width: 36px;
	height: 36px;
}

.avatar {
	display: inline-block;
	vertical-align: middle;
}

.avatar-frame {
	display: inline-block;
	width: 100%;
	height: 100%;
	object-fit: cover;
	background-color: var(--avatar-frame-bg);
	background-size: cover;
	background-repeat: no-repeat;
	background-position: center center;
	border-radius: 50%;
}

.standard-image {
	display: flex;
	justify-content: center;
	align-items: center;
	font-size: 50px;
	font-weight: normal;
}

#user-profile-banner .name {
	margin-left: 200px;
	margin-top: -70px;
}

#user-profile-banner .full-name {
	font-size: x-large;
	font-weight: 500;
}

#user-profile-banner {
	font-size: small;
	font-weight: bold;
	margin-top: 10px;
}

#user-profile-banner .email {
	font-size: small;
	font-weight: 300;
	color: var(--text-muted);
}

#user-profile-banner .avatar {
	margin-left: 20px;
	margin-top: -35px;
}

#user-profile-banner .avatar .avatar {
	width: 140px;
	height: 140px;
	border: 4px solid var(--fg-color);
	border-radius: var(--border-radius-full);
}
